// All values below are editable demonstration assumptions, not field measurements.
export const DEFAULTS=Object.freeze({demand:1200,horizon:1800,workerMinutes:105,breakThreshold:90,evPrice:180000,dieselPrice:100000,chargerCost:20000,dieselCost:2,electricityCost:.25,annualKm:40000,workDays:250,consumption:1.2,chargeEfficiency:.9,chargerPower:120,initialSoc:.8,reserveSoc:.2,battery:240,extraBarriers:0,pedClosed:false,busClosed:false,chargerAvailable:true,optimized:false});
export const PLANS=Object.freeze({A:{id:'A',name:'Single-lane closure',description:'Compact works footprint with a longer pedestrian diversion.',capacity:1050,pedExtra:220,busExtra:650,barriers:18,signs:6,vms:1,workStart:960,workEnd:1130},B:{id:'B',name:'Staged work zone',description:'Move the works edge, retain more road capacity and a shorter walking link.',capacity:1350,pedExtra:80,busExtra:250,barriers:26,signs:8,vms:2,workStart:1010,workEnd:1170}});
export const SCENARIOS={peak:{name:'Morning peak',demand:1200,time:480,feed:true},surge:{name:'Demand surge',demand:1650,time:720,feed:true},quiet:{name:'Clear traffic',demand:700,time:240,feed:true},outage:{name:'Sensor outage',demand:1200,time:600,feed:false}};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function validateAssumptions(raw={}){const a={...DEFAULTS,...raw};const bounds={demand:[0,2400],horizon:[60,3600],workerMinutes:[0,480],breakThreshold:[15,240],evPrice:[50000,500000],dieselPrice:[30000,300000],chargerCost:[0,150000],dieselCost:[.1,6],electricityCost:[.01,2],annualKm:[1000,150000],workDays:[1,366],consumption:[.2,4],chargeEfficiency:[.5,1],chargerPower:[0,350],initialSoc:[.2,1],reserveSoc:[.05,.4],battery:[80,500],extraBarriers:[0,80]};for(const [key,[min,max]]of Object.entries(bounds)){const v=Number(a[key]);if(!Number.isFinite(v)||v<min||v>max)throw new RangeError(`${key} must be between ${min} and ${max}`);a[key]=v;}for(const key of ['pedClosed','busClosed','chargerAvailable','optimized']){if(typeof a[key]!=='boolean')throw new TypeError(`${key} must be true or false`);}if(a.initialSoc<a.reserveSoc)throw new RangeError('Initial battery fraction must meet the reserve');if(!Number.isInteger(a.extraBarriers))throw new RangeError('Barrier count must be a whole number');return a;}
export function traffic(planId='A',raw={},seconds=1800){const a=validateAssumptions(raw);const p=PLANS[planId];if(!p)throw new Error('Unknown plan');const t=clamp(seconds,0,a.horizon);const arrivals=a.demand*t/3600;const served=Math.min(arrivals,p.capacity*t/3600);const queue=Math.max(0,arrivals-served);const length=queue*7;const growth=(a.demand>p.capacity?(a.demand-p.capacity)*7/60:0);const cumulativeWaitVehicleSeconds=.5*queue*t;const qWait=queue/p.capacity*3600;return{planId,duration:t,capacity:p.capacity,arrivals,served,queue,length,tail:Math.max(0,960-length),beyondNetwork:length>960,growth,waitingSeconds:cumulativeWaitVehicleSeconds,observedWaitPerArrival:arrivals?cumulativeWaitVehicleSeconds/arrivals:0,clearanceSeconds:qWait,pedestrian:{reachable:!a.pedClosed,extraMeters:a.pedClosed?null:p.pedExtra,extraSeconds:a.pedClosed?null:p.pedExtra/1.2},bus:{reachable:!a.busClosed,extraMeters:a.busClosed?null:p.busExtra,extraSeconds:a.busClosed?null:p.busExtra/(25/3.6)+qWait},equipment:equipment(planId,a)};}
export function equipment(planId,raw={}){const a=validateAssumptions(raw),p=PLANS[planId];const list=[{type:'Water-filled barriers',quantity:p.barriers+a.extraBarriers,unitKg:380,stock:44},{type:'Traffic signs',quantity:p.signs,unitKg:35,stock:16},{type:'VMS trailers',quantity:p.vms,unitKg:1200,stock:3}];return{items:list,totalKg:list.reduce((s,i)=>s+i.quantity*i.unitKg,0),available:list.every(i=>i.quantity<=i.stock),issues:list.filter(i=>i.quantity>i.stock).map(i=>`${i.type}: ${i.quantity} requested / ${i.stock} available`)};}
export function generateJobs(planId,raw={}){const a=validateAssumptions(raw),e=equipment(planId,a),p=PLANS[planId];const barrierKg=e.items[0].quantity*380;return[
{id:'J1',label:'Barrier delivery · West',equipment:'barriers',start:480,end:540,km:40,kg:Math.ceil(e.items[0].quantity/2)*380,original:'EV-01',site:'West gate'},
{id:'J2',label:'Barrier delivery · East',equipment:'barriers',start:540,end:600,km:60,kg:Math.floor(e.items[0].quantity/2)*380,original:'EV-01',site:'East gate'},
{id:'J3',label:'Signs & final setup',equipment:'signs',start:600,end:660,km:20,kg:p.signs*35,original:'EV-01',site:'Work zone'},
{id:'J4',label:'Afternoon service',equipment:'service',start:690,end:780,km:60,kg:900,original:'EV-01',site:'Service route'},
{id:'J5',label:'VMS deployment',equipment:'vms',start:480,end:570,km:45,kg:p.vms*1200,original:'D-02',site:'Upstream approach'},
{id:'J6',label:'Road plate collection',equipment:'plates',start:540,end:630,km:55,kg:4000,original:'D-03',site:'Adjacent works'}];}
export function vehicles(raw={}){const a=validateAssumptions(raw);return[{id:'EV-01',type:'Electric',payload:6500,battery:a.battery,compatible:['barriers','signs','service']},{id:'D-02',type:'Diesel',payload:6500,compatible:['barriers','signs','service','vms']},{id:'D-03',type:'Diesel',payload:10000,compatible:['barriers','signs','service','vms','plates']}];}
export function evaluateFleet(planId='A',raw={},assignment={}){const a=validateAssumptions(raw),jobs=generateJobs(planId,a),fleet=vehicles(a),eq=equipment(planId,a);const allocations=jobs.map(j=>({...j,vehicle:assignment[j.id]||j.original}));const issues=[...eq.issues];for(const j of allocations){const v=fleet.find(v=>v.id===j.vehicle);if(!v){issues.push(`${j.id}: unknown vehicle`);continue;}if(j.kg>v.payload)issues.push(`${j.id}: ${j.kg.toLocaleString()} kg exceeds ${v.id} payload ${v.payload.toLocaleString()} kg`);if(!v.compatible.includes(j.equipment))issues.push(`${j.id}: ${v.id} cannot carry ${j.equipment}`);}const rows=[],charges=[];let totalBatteryKwh=0;for(const v of fleet){const route=allocations.filter(j=>j.vehicle===v.id).sort((a,b)=>a.start-b.start);let lastEnd=480;let soc=v.type==='Electric'?a.battery*a.initialSoc:null;let minimum=soc;for(const job of route){if(job.start<lastEnd)issues.push(`${v.id}: ${job.id} overlaps an existing job`);const gap=Math.max(0,job.start-lastEnd);let charged=0;if(v.type==='Electric'&&gap>0&&a.chargerAvailable&&a.chargerPower>0){let needed=a.battery*a.reserveSoc;const index=route.indexOf(job);for(let k=route.length-1;k>=index;k--){needed+=route[k].km*a.consumption;if(k>index){const futureGap=Math.max(0,route[k].start-route[k-1].end);needed=Math.max(a.battery*a.reserveSoc,needed-futureGap/60*a.chargerPower*a.chargeEfficiency);}}const required=Math.max(0,needed-soc);charged=Math.min(a.battery-soc,gap/60*a.chargerPower*a.chargeEfficiency,required);if(charged>1e-6){const end=lastEnd+charged/(a.chargerPower*a.chargeEfficiency)*60;const conflicting=charges.some(c=>lastEnd<c.end&&end>c.start);if(conflicting){issues.push(`${v.id}: charger occupied during ${job.id} preparation`);charged=0;}else{charges.push({vehicle:v.id,start:lastEnd,end,kwh:charged,gridKwh:charged/a.chargeEfficiency});soc+=charged;}}}const before=soc,energy=v.type==='Electric'?job.km*a.consumption:null;if(v.type==='Electric'){soc-=energy;totalBatteryKwh+=energy;minimum=Math.min(minimum,soc);if(soc<a.battery*a.reserveSoc-1e-6)issues.push(`${v.id}: ${job.id} finishes ${(a.battery*a.reserveSoc-soc).toFixed(1)} kWh below reserve`);}rows.push({...job,beforeKwh:before,afterKwh:soc,energyKwh:energy,chargedKwh:charged,energyValid:v.type!=='Electric'||soc>=a.battery*a.reserveSoc-1e-6,payloadValid:job.kg<=v.payload});lastEnd=Math.max(lastEnd,job.end);}v.km=route.reduce((s,j)=>s+j.km,0);v.jobs=route.length;v.finalKwh=soc;v.minimumKwh=minimum;}const changes=allocations.filter(j=>j.vehicle!==j.original).map(j=>({jobId:j.id,label:j.label,from:j.original,to:j.vehicle}));return{feasible:issues.length===0,issues:[...new Set(issues)],rows:rows.sort((a,b)=>a.start-b.start||a.id.localeCompare(b.id)),vehicles:fleet,charges,totalBatteryKwh,changes,assignments:Object.fromEntries(allocations.map(j=>[j.id,j.vehicle])),equipment:eq,totalKm:allocations.reduce((s,j)=>s+j.km,0)};}
export function optimizeFleet(planId='A',raw={}){const a=validateAssumptions(raw),base=evaluateFleet(planId,a);if(base.feasible)return{...base,searchCount:1,optimalWithin:'minimum changes within zero-, one- and two-job reassignments'};const jobs=generateJobs(planId,a),fleet=vehicles(a);let count=1,candidates=[];for(const j of jobs)for(const v of fleet){if(v.id===j.original)continue;const result=evaluateFleet(planId,a,{[j.id]:v.id});count++;if(result.feasible)candidates.push(result);}if(!candidates.length){for(let i=0;i<jobs.length;i++)for(let j=i+1;j<jobs.length;j++)for(const v of fleet)for(const w of fleet){if(v.id===jobs[i].original||w.id===jobs[j].original)continue;const result=evaluateFleet(planId,a,{[jobs[i].id]:v.id,[jobs[j].id]:w.id});count++;if(result.feasible)candidates.push(result);}}candidates.sort((x,y)=>x.changes.length-y.changes.length||(y.vehicles[0].km-x.vehicles[0].km));return{...(candidates[0]||base),searchCount:count,optimalWithin:'minimum changes within zero-, one- and two-job reassignments'};}
export function tco(raw={},evKmOverride){const a=validateAssumptions(raw),evKm=evKmOverride??a.annualKm;if(!Number.isFinite(evKm)||evKm<0||evKm>3*a.annualKm)throw new RangeError('Annual EV distance is outside fleet mileage');const dieselKm=Math.max(0,3*a.annualKm-evKm);const dieselPerKm=.3*a.dieselCost;const evPerKm=a.consumption/a.chargeEfficiency*a.electricityCost;const baselineAnnual=3*a.annualKm*dieselPerKm+18000;const mixedAnnual=dieselKm*dieselPerKm+evKm*evPerKm+15000;const baselineCapex=3*a.dieselPrice,mixedCapex=2*a.dieselPrice+a.evPrice+a.chargerCost;const baselineResidual=60000,mixedResidual=80000;const years=Array.from({length:6},(_,year)=>({year,diesel:baselineCapex+baselineAnnual*year-(year===5?baselineResidual:0),mixed:mixedCapex+mixedAnnual*year-(year===5?mixedResidual:0)}));const diesel=years[5].diesel,mixed=years[5].mixed;return{diesel,mixed,saving:diesel-mixed,baselineAnnual,mixedAnnual,baselineCapex,mixedCapex,baselineResidual,mixedResidual,evKm,dieselKm,gridKwh:evKm*a.consumption/a.chargeEfficiency,years,basis:'Three new diesel vehicles versus two new diesel + one new electric; undiscounted AUD, maintenance included, tax/finance excluded; year-5 residual applied.'};}
export function assessApproach({x,y,speed,direction=1},worker={x:1000,y:18},radius=16){const along=(worker.x-direction*radius-x)*direction;const inside=Math.abs(worker.x-x)<=radius;const inPath=Math.abs(worker.y-y)<=8;const closing=speed>0&&((direction>0&&x<=worker.x)||(direction<0&&x>=worker.x));const ttc=inPath&&inside?0:inPath&&closing?Math.max(0,along)/speed:null;return{ttc,inPath,closing,critical:ttc!==null&&ttc<3,warning:ttc!==null&&ttc<6};}
export function sceneTracks(time,queue,injectAt=null){const tracks=[];const visible=Math.min(32,Math.ceil(queue));for(let i=0;i<visible;i++)tracks.push({id:`Q${i}`,x:950-i*7,y:0,speed:0,type:i%6===0?'truck':'car',queued:true});const tail=960-queue*7;for(let i=0;i<9;i++){const x=((time*10+i*139)%1200);if(x<tail-25||x>1150)tracks.push({id:`M${i}`,x,y:0,speed:10,type:i%4===0?'truck':'car',queued:false});}for(let i=0;i<7;i++)tracks.push({id:`W${i}`,x:1200-((time*13+i*163)%1200),y:-28,speed:13,direction:-1,type:i===3?'bus':'car'});if(injectAt!==null&&time>=injectAt&&time<=injectAt+12)tracks.push({id:'H-01',x:938+(time-injectAt)*10,y:18,speed:10,direction:1,type:'truck',hazard:true});return tracks;}
export function snapshot({plan='A',assumptions={},time=480,feed=true,injectAt=null,lastBreak=0,acknowledged=[],version=1,optimized=false}={}){const a=validateAssumptions(assumptions),tr=traffic(plan,a,time),forecast=traffic(plan,a,a.horizon);const tracks=sceneTracks(time,tr.queue,injectAt);const hazard=tracks.find(t=>t.hazard),approach=hazard?assessApproach(hazard):{ttc:null,critical:false,warning:false};const continuous=Math.max(0,a.workerMinutes+time/60-lastBreak);const fatigue=continuous>=a.breakThreshold;const queueStatus=!feed?'unknown':tr.length>=200?'high':tr.length>=70?'watch':'clear';const safetyStatus=!feed?'unknown':approach.critical?'high':approach.warning||fatigue?'watch':'clear';const runId=`RPM-01-${plan}-v${version}`;const events=[];const add=(id,type,severity,title,detail,module)=>events.push({id:`${runId}-${id}-${severity}`,runId,time,type,severity,title,detail,module,acknowledged:acknowledged.includes(`${runId}-${id}-${severity}`)});if(!feed)add('feed','data','unknown','Sensor feed unavailable','Live safety and queue readings are unknown. Planning estimates remain available.','SYSTEM');else{if(approach.warning)add('approach','hazard',approach.critical?'high':'watch','Vehicle approaching worker zone',`Simulated H-01 approaches the configured zone in ${approach.ttc.toFixed(1)} s. Notify the controller and inspect the replay.`,'R1');if(fatigue)add('shift','duty','watch','Controller relief suggested',`${Math.floor(continuous)} min continuous duty exceeds the ${a.breakThreshold}-min demo reminder. This is a workload proxy.`,'R1');if(queueStatus!=='clear')add('queue','queue',queueStatus==='high'?'high':'watch',queueStatus==='high'?'Queue tail warning active':'Queue building upstream',`${Math.round(tr.length)} m queue, growing ${tr.growth.toFixed(1)} m/min under current demand.`,'R2');}const fleet=optimized?optimizeFleet(plan,a):evaluateFleet(plan,a);if(!fleet.feasible)add('fleet','fleet','watch','Dispatch plan needs adjustment',fleet.issues[0],'R4');if(!tr.pedestrian.reachable)add('ped','access','high','Pedestrian route disconnected','Reopen an alternative pedestrian link before accepting this plan.','R3');if(!tr.bus.reachable)add('bus','access','high','Bus route disconnected','Provide a bus alternative before accepting this plan.','R3');const vms=!feed?'DATA LOST\nCHECK SITE':queueStatus==='high'?'QUEUE AHEAD\nPREPARE TO STOP':queueStatus==='watch'?'SLOW TRAFFIC\nAHEAD':'ROADWORKS\nTAKE CARE';const speed=!feed?null:queueStatus==='high'?40:queueStatus==='watch'?60:80;const cost=tco(a);return{runId,version,plan,time,source:'simulation',feed,traffic:tr,forecast,tracks:feed?tracks:[],worker:{continuous,fatigue,ttc:feed?approach.ttc:null,status:safetyStatus},queue:{status:queueStatus,length:feed?tr.length:null,tail:feed?tr.tail:null,growth:feed?tr.growth:null,vms,speed},fleet,cost,events};}
export function comparePlans(raw={}){const a=validateAssumptions(raw);return Object.keys(PLANS).map(id=>{const tr=traffic(id,a,a.horizon),fleet=optimizeFleet(id,a);return{plan:id,traffic:tr,fleet,feasible:tr.pedestrian.reachable&&tr.bus.reachable&&fleet.feasible};});}
export function formatTime(minutes){minutes=Math.round(minutes);return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(Math.round(minutes%60)).padStart(2,'0')}`;}
